function applyTheme(next){theme={...DEFAULT_THEME,...next};Object.entries(theme).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));document.querySelectorAll('[data-theme-key]').forEach(i=>{if(theme[i.dataset.themeKey])i.value=theme[i.dataset.themeKey]});}
function loadTheme(){try{const saved=JSON.parse(localStorage.getItem(THEME_KEY)||'null');applyTheme(saved&&typeof saved==='object'?saved:DEFAULT_THEME);const ar=localStorage.getItem(AUTO_REFRESH_KEY);autoRefresh=ar===null?true:ar==='1';}catch{applyTheme(DEFAULT_THEME);autoRefresh=true}const t=document.getElementById('autoRefreshToggle');if(t)t.checked=autoRefresh}
function saveTheme(){localStorage.setItem(THEME_KEY,JSON.stringify(theme));setStatus('Theme saved.','ok')}
