async function loadState(){
  try {
    const r=await window.maddenAPI.loadAppState();
    const d=r?.state||{};
    slip=Array.isArray(d.slip)?d.slip:JSON.parse(localStorage.getItem(SLIP_KEY)||'[]');
    history=Array.isArray(d.history)?d.history:JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');
    wallets=(d.wallets&&typeof d.wallets==='object')?d.wallets:(JSON.parse(localStorage.getItem(WALLETS_KEY)||'{}')||{});
    balance=Number.isFinite(Number(d.balance))?Number(d.balance):0;
    economy=d.economy&&typeof d.economy==='object'?d.economy:freshEconomy();
    if(!Array.isArray(slip))slip=[]; if(!Array.isArray(history))history=[];
  } catch {
    try { slip=JSON.parse(localStorage.getItem(SLIP_KEY)||'[]'); history=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]'); wallets=JSON.parse(localStorage.getItem(WALLETS_KEY)||'{}')||{}; } catch { slip=[]; history=[]; wallets={}; }
    balance=0; economy=freshEconomy();
  }
}
function persistAppState(){
  const state={slip,history,balance:Math.max(0,Number(balance)||0),economy,wallets};
  window.maddenAPI.saveAppState(state).catch(()=>{});
  // Keep legacy browser storage as a compatibility fallback.
  try{localStorage.setItem(SLIP_KEY,JSON.stringify(slip));localStorage.setItem(HISTORY_KEY,JSON.stringify(history));localStorage.setItem(BALANCE_KEY,String(state.balance));localStorage.setItem(ECONOMY_KEY,JSON.stringify(economy));localStorage.setItem(WALLETS_KEY,JSON.stringify(wallets));}catch{}
}
function saveState(){persistAppState();renderBalance();}
function renderBalance(){const e=document.getElementById('balance');if(e)e.textContent=franchiseLoaded?money(balance):'—';const s=document.getElementById('balanceSave');if(s)s.innerHTML=franchiseLoaded?`FRANCHISE SAVE <b>${escapeHtml(currentFranchiseLabel())}</b>`:'Select a Franchise save';}
function activateWallet(key){if(!key)return;let existing=wallets[key];if(!existing){const legacy=legacyFranchiseKey();if(legacy&&legacy!==key&&wallets[legacy]){existing=wallets[legacy];wallets[key]=existing;delete wallets[legacy];}}if(existing&&typeof existing==='object'){balance=Number.isFinite(Number(existing.balance))?Number(existing.balance):500;economy=existing.economy&&typeof existing.economy==='object'?existing.economy:freshEconomy();}else{wallets[key]={balance:Math.max(0,Number(balance)||500),economy:JSON.parse(JSON.stringify(economy&&typeof economy==='object'?economy:freshEconomy()))};balance=wallets[key].balance;economy=wallets[key].economy;}activeWalletKey=key;saveWallet();}
function saveWallet(){if(!activeWalletKey)return;wallets[activeWalletKey]={balance:Math.max(0,Number(balance)||0),economy};persistAppState();renderBalance();}
function americanToDecimal(a){a=Number(a);return a>=0?1+a/100:1+100/Math.abs(a)}function decimalToAmerican(d){return d>=2?'+'+Math.round((d-1)*100):'-'+Math.round(100/(d-1))}
