function teamLogoForName(name,small=false){const n=String(name||'').trim();const ab=teamNameToAb[n];return logoMarkup(ab||n,n,small)}
function betTeamName(v,fallback){return String(v||fallback||'').trim()}
function currentFranchiseLabel(){return String(currentData?.fileName||'').trim()||'No Franchise loaded'}
function currentFranchiseKey(){if(!currentData)return '';return String(hashString(`${currentData.fileName||''}|${currentData.gameYear||''}`))}
function legacyFranchiseKey(){if(!currentData)return '';const sig=(currentData.games||[]).map(g=>[g.SeasonWeek,g.SeasonGameNum,g.AwayTeam,g.HomeTeam].join(':')).join('|');return String(hashString(`${currentData.fileName||''}|${currentData.gameYear||''}|${sig}`))}
function betBelongsToCurrentFranchise(b){if(!currentData||!b)return false;const key=currentFranchiseKey();if(b.franchiseKey===key)return true;return String(b.franchiseName||'')===currentFranchiseLabel()&&String(b.franchiseYear??'')===String(currentData.gameYear??'')}
function betSaveLabel(b){return String(b?.franchiseName||'').trim()||'Save not recorded'}
function betSaveClass(b){return b?.franchiseName?'history-save':'history-save missing'}

function logoMarkup(ab,name,small=false){const key=String(ab||'').toUpperCase();const n=String(name||'').trim();const url=teamLogoUrls[key]||relocationLogoUrls[n];const fallback=String(ab||name||'?').slice(0,3).toUpperCase();if(!url)return `<div class="logo-fallback${small?' logo-sm':''}">${fallback}</div>`;const cls=relocationLogoUrls[n]&&!teamLogoUrls[key]?'team-logo-img relocation-logo':'team-logo-img';return `<img class="${cls}${small?' logo-sm':''}" src="${url}" alt="${n||key}" title="${n||key}" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"> <div class="logo-fallback${small?' logo-sm':''}" style="display:none">${fallback}</div>`}
function teamLogoCell(ab,name){return `<div class="logo">${logoMarkup(ab,name)}</div>`}
function gameKey(g){return [g.phase||'regular',g.phaseWeek??g.SeasonWeek,g.SeasonGameNum,g.AwayTeam,g.HomeTeam].join('|')}
function isPlayed(g){return g?.isPlayed===true}
function gameTimeMinutes(g){const n=g?.gameTimeMinutes;return n===null||n===undefined||n===''||!Number.isFinite(Number(n))?null:Number(n)}function formatGameTime(g){const mins=gameTimeMinutes(g);if(mins===null)return 'TIME TBD';const h=Math.floor(mins/60)%24,m=mins%60;const ap=h>=12?'PM':'AM';const hh=(h%12)||12;return `${hh}:${String(m).padStart(2,'0')} ${ap}`}function daySort(g){const order={Thursday:0,Friday:1,Saturday:2,Sunday:3,Monday:4,Tuesday:5,Wednesday:6};return order[String(g.DayOfWeek||'')]??9}function gameSort(a,b){const dayDelta=daySort(a)-daySort(b);if(dayDelta)return dayDelta;const at=gameTimeMinutes(a),bt=gameTimeMinutes(b);if(at!==null&&bt!==null&&at!==bt)return at-bt;if(at!==null&&bt===null)return -1;if(at===null&&bt!==null)return 1;return Number(a.SeasonGameNum)-Number(b.SeasonGameNum)}function currentGameSet(){if(!currentData)return[]; const phase=window.selectedPhase||'regular'; const w=Number(document.getElementById('week').value); return games.filter(g=>String(g.phase||'regular')===phase&&Number(g.phaseWeek)===w).sort(gameSort)}
function statsForTeam(id){const rows=games.filter(g=>isPlayed(g)&&String(g.phase||'regular')==='regular'&&(g.AwayTeam===id||g.HomeTeam===id));let w=0,l=0,t=0,pf=0,pa=0;for(const g of rows){const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0;if(g.AwayTeam===id){pf+=a;pa+=h;if(a>h)w++;else if(a<h)l++;else t++;}else{pf+=h;pa+=a;if(h>a)w++;else if(h<a)l++;else t++;}}return{w,l,t,pf,pa,gp:rows.length}}
function hashString(str){let h=2166136261;for(let i=0;i<String(str).length;i++){h^=String(str).charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function priceFromProbability(p){const q=Math.min(.67,Math.max(.33,Number(p)||.5));return q>=.5?-Math.round(100*q/(1-q)):Math.round(100*(1-q)/q)}
function juicePair(g,kind,spread){const magnitude=Math.abs(Number(spread)||0);let fav=-110,dog=-110;if(kind==='spread'){if(magnitude>=7)fav=-115,dog=-105;else if(magnitude>=3.5)fav=-112,dog=-108;else if(magnitude>=1.5)fav=-110,dog=-110;const n=hashString(gameKey(g))%3;if(n===0&&fav===-110){fav=-108;dog=-112}else if(n===2&&fav===-110){fav=-112;dog=-108}}else{const n=hashString(gameKey(g)+'|'+kind)%5;if(n===0){fav=-115;dog=-105}else if(n===1){fav=-112;dog=-108}else if(n===2){fav=-108;dog=-112}}return{fav,dog}}
function modelLine(g){const a=statsForTeam(g.AwayTeam),h=statsForTeam(g.HomeTeam);const ar=a.gp?((a.pf-a.pa)/a.gp):0,hr=h.gp?((h.pf-h.pa)/h.gp):0;const margin=(hr-ar)+2.5;const total=a.gp&&h.gp?((a.pf+a.pa)/a.gp+(h.pf+h.pa)/h.gp)/2:44.5;let homeProb=1/(1+Math.exp(-margin/6));homeProb=Math.min(.82,Math.max(.18,homeProb));const vig=.045;let hp=homeProb*(1-vig/2),ap=(1-homeProb)*(1-vig/2);const homeML=hp>=.5?-Math.round(100*hp/(1-hp)):Math.round(100*(1-hp)/hp);const awayML=ap>=.5?-Math.round(100*ap/(1-ap)):Math.round(100*(1-ap)/ap);const spread=Math.round(margin*2)/2;const lineTotal=Math.round(total*2)/2;const spreadJuice=juicePair(g,'spread',spread);const totalJuice=juicePair(g,'total',lineTotal);const awayFav=spread<0,homeFav=spread>0;const pickem=spread===0;const totalOverFav=(hashString(gameKey(g)+'|total-side')%2)===0;return{awayML:fmtOdds(awayML),homeML:fmtOdds(homeML),awaySpread:pickem?-110:(awayFav?spreadJuice.fav:spreadJuice.dog),homeSpread:pickem?-110:(homeFav?spreadJuice.fav:spreadJuice.dog),spread,over:totalOverFav?totalJuice.fav:totalJuice.dog,under:totalOverFav?totalJuice.dog:totalJuice.fav,total:lineTotal,aRec:`${a.w}-${a.l}${a.t?'-'+a.t:''}`,hRec:`${h.w}-${h.l}${h.t?'-'+h.t:''}`}}
function propOdds(m,side){const scales={passYds:15,passTD:.35,completions:1.5,rushYds:6,rushAtt:1.5,recYds:6,receptions:.9};const scale=scales[m.stat]||5;const edge=(Number(m.average)-Number(m.line))/scale*(side==='over'?1:-1);const fair=.5+Math.max(-.05,Math.min(.05,edge*.07));const vig=.045;return priceFromProbability(fair*(1+vig/2))}

function market(label,market,display,g,kind){const odds=Number(display);return `<button class="market" data-add='${encodeURIComponent(JSON.stringify({label,market,display,odds,gameId:gameKey(g),gameIndex:g.index,week:g.week,away:g.awayName,home:g.homeName,kind,line:g.line||null}))}'><span class="m">${market}</span><b>${display}</b></button>`}
function renderGames(){const c=document.getElementById('games');const list=currentGameSet();if(!franchiseLoaded){c.innerHTML='<div class="empty" style="grid-column:1/-1">Import your Madden 27 Franchise to load games and odds.</div>';return}if(!list.length){c.innerHTML='<div class="empty" style="grid-column:1/-1">No games found for this week.</div>';return}c.innerHTML=list.map(g=>{const l=modelLine(g);g.line=l.spread;const played=isPlayed(g);const result=played?`<div class="result"><span>${g.GameStatus}</span><b>${g.awayName} ${g.AwayScore} — ${g.HomeScore} ${g.homeName}</b></div>`:`<div class="market-board"><div class="market-team-label"><span>AWAY</span><b>${g.awayName}</b></div><div class="market-row">${market(g.awayName+' ML','Moneyline',l.awayML,g,'mlA')}${market(g.awayName+' '+(l.spread>0?'+':'')+l.spread,'Spread',(l.spread>0?'+':'')+l.spread+' '+l.awaySpread,g,'sprA',l.spread)}${market('Over '+l.total,'Total','O '+l.total+' '+l.over,g,'over',l.total)}</div><div class="market-team-label"><span>HOME</span><b>${g.homeName}</b></div><div class="market-row">${market(g.homeName+' ML','Moneyline',l.homeML,g,'mlH')}${market(g.homeName+' '+(l.spread>0?'-':'+' )+Math.abs(l.spread),'Spread',(l.spread>0?'-':'+' )+Math.abs(l.spread)+' '+l.homeSpread,g,'sprH',-l.spread)}${market('Under '+l.total,'Total','U '+l.total+' '+l.under,g,'under',l.total)}</div></div>`;return `<article class="game"><div class="gamehead"><span>${g.phaseLabel||'Regular Season'} • WEEK ${Number(g.phaseWeek||g.week+1)} • GAME ${Number(g.SeasonGameNum)+1}</span><span>${String(g.DayOfWeek||'').toUpperCase()} • ${formatGameTime(g)} &nbsp; ${played?'FINAL':'UPCOMING'}</span></div><div class="teams"><div class="team">${teamLogoCell(g.awayAb,g.awayName)}<strong>${g.awayName}</strong><div class="record">${l.aRec}</div></div><div class="vs">@</div><div class="team">${teamLogoCell(g.homeAb,g.homeName)}<strong>${g.homeName}</strong><div class="record">${l.hRec}</div></div></div>${result}</article>`}).join('');c.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(decodeURIComponent(b.dataset.add));x.odds=parseOddsDisplay(x.display);slip.push({...x,key:crypto.randomUUID()});saveState();renderSlip();setStatus('Selection added to bet slip.','ok')}));}
function parseOddsDisplay(s){const m=String(s).match(/([+-]\d+)$/);return m?Number(m[1]):-110}
function renderSlip(){const s=document.getElementById('slip');document.getElementById('count').textContent=slip.length;if(!slip.length){s.innerHTML='<div class="empty">Your bet slip is empty.<br><br>Click a market to add it.</div>';['betType','combined'].forEach(id=>document.getElementById(id).textContent='—');document.getElementById('profit').textContent='$0.00';document.getElementById('return').textContent='$0.00';return}s.innerHTML=slip.map(b=>`<div class="bet"><div class="bettop"><div style="display:flex;gap:8px;min-width:0"><div class="slip-team-stack">${teamLogoForName(b.away,true)}${teamLogoForName(b.home,true)}</div><div><div class="betname">${b.label}</div><div class="betmeta">${b.market} • ${b.kind==='mlA'||b.kind==='sprA'?'AWAY • '+b.away:b.kind==='mlH'||b.kind==='sprH'?'HOME • '+b.home:'GAME TOTAL'} • ${b.away} @ ${b.home}</div></div></div><button class="x" data-remove="${b.key}">×</button></div><div style="margin-top:6px;font-weight:800">${b.display}</div></div>`).join('');s.querySelectorAll('[data-remove]').forEach(x=>x.addEventListener('click',()=>{slip=slip.filter(b=>b.key!==x.dataset.remove);saveState();renderSlip()}));const dec=slip.reduce((v,b)=>v*americanToDecimal(b.odds),1),w=Math.max(0,Number(document.getElementById('wager').value)||0);document.getElementById('betType').textContent=slip.length===1?'STRAIGHT':'PARLAY';document.getElementById('combined').textContent=decimalToAmerican(dec);document.getElementById('profit').textContent=money(w*(dec-1));document.getElementById('return').textContent=money(w*dec)}
function settleBet(b,g){const kind=b.kind;const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0;let win=null;if(kind==='mlA')win=a>h;else if(kind==='mlH')win=h>a;else if(kind==='over')win=a+h>Number(b.line);else if(kind==='under')win=a+h<Number(b.line);else if(kind==='sprA')win=a+Number(b.line)>h;else if(kind==='sprH')win=h+Number(b.line)>a;else if(kind==='propOver'||kind==='propUnder'){const row=(currentData?.playerGameStats||[]).find(r=>String(r.playerId)===String(b.playerId)&&String(r.gameIndex)===String(g.index));const value=row?.stats?.[b.propStat];if(!Number.isFinite(Number(value)))return 'void';win=kind==='propOver'?Number(value)>Number(b.line):Number(value)<Number(b.line);b.actual=value;}else return null;return win?'won':'lost'}
function settlePending(){if(!games.length||!history.length||!franchiseLoaded)return;const key=currentFranchiseKey();const label=currentFranchiseLabel();const year=currentData?.gameYear??null;let changed=false;for(const bet of history){if(bet.status!=='pending')continue;if(!bet.franchiseKey||bet.franchiseKey!==key){if(betBelongsToCurrentFranchise(bet)){bet.franchiseKey=key;bet.franchiseName=label;bet.franchiseYear=year;changed=true;}else continue;}const legs=bet.legs||[];const results=legs.map(l=>{const g=games.find(x=>l.gameIndex!==undefined&&l.gameIndex!==null&&String(x.index)===String(l.gameIndex))||games.find(x=>gameKey(x)===l.gameId)||games.find(x=>Number(x.SeasonWeek)===Number(l.week)&&String(x.AwayTeam)===String(l.away)&&String(x.HomeTeam)===String(l.home));return g&&isPlayed(g)?settleBet(l,g):null});if(results.length&&results.every(Boolean)){const hasLoss=results.includes('lost');const hasWin=results.includes('won');const allVoid=results.every(x=>x==='void');if(allVoid){bet.status='void';bet.settledAt=new Date().toISOString();bet.profit=0;bet.payout=bet.wager;balance+=bet.wager;changed=true;continue;}if(hasLoss){bet.status='lost';bet.settledAt=new Date().toISOString();bet.profit=-bet.wager;bet.payout=0;changed=true;continue;}const activeResults=results.filter(x=>x!=='void');if(activeResults.length&&activeResults.every(x=>x==='won')){bet.status='won';bet.settledAt=new Date().toISOString();const dec=bet.decimalOdds||1;bet.profit=bet.wager*(dec-1);bet.payout=bet.wager*dec;if(bet.status==='won')balance+=bet.payout;changed=true;}}}if(changed){saveWallet();renderActiveBets();renderHistory();renderStats()}}
function placeBet(){if(!slip.length){setStatus('Add a selection first.','err');return}if(!franchiseLoaded){setStatus('Import a Franchise before placing a wager.','err');return}const wager=Math.max(1,Number(document.getElementById('wager').value)||0);if(wager>balance){setStatus('Wager exceeds your available balance.','err');return}const dec=slip.reduce((v,b)=>v*americanToDecimal(b.odds),1);history.unshift({id:crypto.randomUUID(),placedAt:new Date().toISOString(),status:'pending',wager,decimalOdds:dec,americanOdds:decimalToAmerican(dec),profit:0,payout:0,franchiseName:currentFranchiseLabel(),franchiseYear:currentData?.gameYear??null,franchiseKey:currentFranchiseKey(),legs:slip.map(x=>({...x}))});balance-=wager;slip=[];saveWallet();renderSlip();renderActiveBets();renderHistory();setStatus('Bet placed. Your wager has been deducted from the balance.','ok')}

function renderStandings(){const rows=teams.filter(t=>String(t.name||'').trim().toLowerCase()!=='practice').map(t=>{const s=statsForTeam(t.id);return{...t,...s}}).sort((a,b)=>(b.w-a.w)||(b.pf-b.pa)-(a.pf-a.pa));document.getElementById('standings').innerHTML=`<table class="table"><thead><tr><th>Team</th><th>W</th><th>L</th><th>T</th><th>PF</th><th>PA</th><th>Diff</th></tr></thead><tbody>${rows.map(t=>`<tr><td><div class="standings-team">${teamLogoCell(t.abbreviation||t.ab||t.shortName,t.name||t.id.slice(-8)).replace('class="logo"','class="logo" style="margin:0"')}<b>${t.name||t.id.slice(-8)}</b></div></td><td>${t.w}</td><td>${t.l}</td><td>${t.t}</td><td>${t.pf}</td><td>${t.pa}</td><td class="${t.pf-t.pa>=0?'pos':'neg'}">${t.pf-t.pa>=0?'+':''}${t.pf-t.pa}</td></tr>`).join('')}</tbody></table>`}
function activeBetsHtml(active){return active.map(b=>{const gamesText=[...new Set((b.legs||[]).map(l=>`${betTeamName(l.away,l.awayName)} @ ${betTeamName(l.home,l.homeName)}`))].join(' • ');const first=b.legs?.[0]||{};const firstAway=betTeamName(first.away,first.awayName);const firstHome=betTeamName(first.home,first.homeName);return `<article class="active-card"><div class="active-card-head"><div style="min-width:0"><div style="display:flex;align-items:center;gap:9px"><div class="active-match-logos">${teamLogoForName(firstAway,true)}${teamLogoForName(firstHome,true)}</div><div style="min-width:0"><div class="active-title">${b.legs?.length>1?`${b.legs.length}-Leg Parlay`:'Straight Bet'}</div><div class="active-game">${gamesText}</div></div></div><div class="save-badge" title="Franchise save used when this wager was placed">FRANCHISE SAVE <b>${betSaveLabel(b)}</b></div></div><span class="active-status">PENDING</span></div><div class="active-legs">${(b.legs||[]).map(l=>`<div class="active-leg"><span style="display:flex;align-items:center;gap:7px">${teamLogoForName(betTeamName(l.away,l.awayName),true)}${teamLogoForName(betTeamName(l.home,l.homeName),true)}<span>${l.label}</span></span><b>${l.display}</b></div>`).join('')}</div><div class="active-foot"><span>Wager <b>${money(b.wager)}</b></span><span>Potential return <b>${money(b.wager*(b.decimalOdds||1))}</b></span><button class="btn" data-view-slip="${b.id}">View Slip</button><button class="btn danger" data-cancel-bet="${b.id}">Cancel Bet</button></div></article>`}).join('')}
function cancelBet(id){const bet=history.find(b=>b.id===id);if(!bet||bet.status!=='pending')return;const ok=confirm(`Cancel this wager for ${money(bet.wager)}?\n\nThe full wager amount will be refunded to your bankroll.`);if(!ok)return;bet.status='cancelled';bet.cancelledAt=new Date().toISOString();bet.settledAt=bet.cancelledAt;bet.profit=0;bet.payout=0;balance+=Number(bet.wager)||0;saveWallet();saveState();renderActiveBets();renderHistory();renderStats();renderBalance();setStatus(`Bet cancelled. ${money(bet.wager)} refunded to your bankroll.`,'ok')}
function bindViewSlipButtons(root){root.querySelectorAll('[data-view-slip]').forEach(btn=>btn.addEventListener('click',()=>openHistorySlip(btn.dataset.viewSlip)));root.querySelectorAll('[data-cancel-bet]').forEach(btn=>btn.addEventListener('click',()=>cancelBet(btn.dataset.cancelBet)))}
function renderActiveBets(){const c=document.getElementById('activeBets');const count=document.getElementById('activeBetCount');const active=history.filter(b=>b.status==='pending');if(count)count.textContent=`${active.length} open wager${active.length===1?'':'s'}`;if(!active.length){c.innerHTML='<div class="empty">No active bets. Place a wager and it will appear here until the Franchise result is available.</div>';return}c.innerHTML=`<div class="active-stack">${activeBetsHtml(active)}</div>`;bindViewSlipButtons(c)}
function renderStats(){const c=document.getElementById('statsContent');if(!c)return;if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Franchise first to view sportsbook statistics.</div>';return}const bets=history.filter(b=>betBelongsToCurrentFranchise(b));const active=bets.filter(b=>b.status==='pending');const cancelled=bets.filter(b=>b.status==='cancelled');const settled=bets.filter(b=>['won','lost','void'].includes(b.status));const wins=bets.filter(b=>b.status==='won');const losses=bets.filter(b=>b.status==='lost');const wagered=settled.reduce((n,b)=>n+Number(b.wager||0),0);const payouts=wins.reduce((n,b)=>n+Number(b.payout||0),0);const profit=settled.reduce((n,b)=>n+Number(b.profit||0),0);const roi=wagered?profit/wagered*100:0;const winRate=settled.length?wins.length/settled.length*100:0;const avg=wagered/Math.max(1,settled.length);const biggestWin=wins.reduce((m,b)=>Math.max(m,Number(b.profit||0)),0);const biggestLoss=losses.reduce((m,b)=>Math.min(m,Number(b.profit||0)),0);const straight=settled.filter(b=>(b.legs||[]).length<=1).length;const parlays=settled.filter(b=>(b.legs||[]).length>1).length;const recent=settled.slice().sort((a,b)=>new Date(b.settledAt||b.placedAt)-new Date(a.settledAt||a.placedAt)).slice(0,10);const form=recent.map(b=>`<span class="stat-form ${b.status==='won'?'win':b.status==='lost'?'loss':'void'}">${b.status==='won'?'W':b.status==='lost'?'L':'V'}</span>`).join('');c.innerHTML=`<div class="cards stats-cards"><div class="mini"><div class="note">TOTAL BETS</div><b>${bets.length}</b><div class="note">${active.length} active • ${cancelled.length} cancelled</div></div><div class="mini"><div class="note">RECORD</div><b>${wins.length}-${losses.length}</b><div class="note">${winRate.toFixed(1)}% win rate</div></div><div class="mini"><div class="note">NET PROFIT / LOSS</div><b class="${profit>=0?'pos':'neg'}">${money(profit)}</b><div class="note">${roi.toFixed(1)}% ROI</div></div></div><div class="cards stats-cards"><div class="mini"><div class="note">TOTAL WAGERED</div><b>${money(wagered)}</b><div class="note">Settled wagers only</div></div><div class="mini"><div class="note">TOTAL PAYOUTS</div><b>${money(payouts)}</b><div class="note">Winning returns</div></div><div class="mini"><div class="note">AVERAGE WAGER</div><b>${money(avg)}</b><div class="note">Per settled bet</div></div></div><div class="stats-grid"><article class="hero"><div class="eyebrow">BETTING BREAKDOWN</div><div class="stats-list"><div><span>Wins</span><b class="pos">${wins.length}</b></div><div><span>Losses</span><b class="neg">${losses.length}</b></div><div><span>Cancelled</span><b>${cancelled.length}</b></div><div><span>Pending</span><b>${active.length}</b></div><div><span>Straight bets</span><b>${straight}</b></div><div><span>Parlays</span><b>${parlays}</b></div><div><span>Biggest win</span><b class="pos">${money(biggestWin)}</b></div><div><span>Biggest loss</span><b class="neg">${money(biggestLoss)}</b></div></div></article><article class="hero"><div class="eyebrow">RECENT FORM</div><div class="form-row">${form||'<span class="note">No settled wagers yet.</span>'}</div><div class="note" style="margin-top:14px">Latest ${recent.length} settled wagers, newest first.</div><div class="stats-progress"><span style="width:${Math.max(0,Math.min(100,winRate))}%"></span></div><div class="note">Win rate: ${winRate.toFixed(1)}%</div></article></div><div class="hero"><div class="eyebrow">WHAT THE NUMBERS MEAN</div><div class="note">Net profit is your winnings minus settled wagers lost. ROI is net profit divided by total settled amount wagered. Cancelled wagers are refunded and excluded from performance metrics.</div></div>`}

function renderHistory(){const c=document.getElementById('history');const active=history.filter(b=>b.status==='pending');const activeWrap=document.getElementById('historyActiveBets');const activeCount=document.getElementById('historyActiveBetCount');if(activeCount)activeCount.textContent=`${active.length} open wager${active.length===1?'':'s'}`;if(activeWrap)activeWrap.innerHTML=active.length?`<div class="active-stack">${activeBetsHtml(active)}</div>`:'<div class="empty">No active bets.</div>';if(activeWrap)bindViewSlipButtons(activeWrap);const settled=history.filter(b=>b.status!=='pending');const count=document.getElementById('settledBetCount');if(count)count.textContent=`${settled.length} settled wager${settled.length===1?'':'s'}`;if(!settled.length){c.innerHTML='<div class="empty">No settled bets yet.</div>';return}c.innerHTML=`<table class="table"><thead><tr><th>Date</th><th>Franchise Save</th><th>Type</th><th>Odds</th><th>Wager</th><th>Status</th><th>P/L</th><th></th></tr></thead><tbody>${settled.map(b=>`<tr><td>${new Date(b.placedAt).toLocaleString()}</td><td><span class="${betSaveClass(b)}" title="${betSaveLabel(b)}">${betSaveLabel(b)}</span></td><td><div class="history-team-stack">${(b.legs||[]).slice(0,1).map(l=>teamLogoForName(betTeamName(l.away,l.awayName),true)+teamLogoForName(betTeamName(l.home,l.homeName),true)).join('')}<span>${b.legs?.length>1?'Parlay':'Straight'}</span></div></td><td>${b.americanOdds}</td><td>${money(b.wager)}</td><td class="${b.status==='won'?'pos':b.status==='lost'?'neg':b.status==='cancelled'?'':''}">${b.status.toUpperCase()}</td><td class="${b.profit>=0?'pos':'neg'}">${money(b.profit)}</td><td><button class="btn" data-view-slip="${b.id}">View Slip</button></td></tr>`).join('')}</tbody></table>`;bindViewSlipButtons(c)}
function openHistorySlip(id){const b=history.find(x=>x.id===id);if(!b)return;document.getElementById('slipModalTitle').textContent=`${b.status.toUpperCase()} • ${b.legs?.length>1?'PARLAY':'STRAIGHT'} • ${betSaveLabel(b)}`;const body=document.getElementById('slipModalBody');body.innerHTML=`<div class="save-badge" style="margin-top:0;margin-bottom:8px">FRANCHISE SAVE <b>${betSaveLabel(b)}</b></div>${(b.legs||[]).map(l=>{const g=games.find(x=>gameKey(x)===l.gameId);let outcome='';let actual='';if(b.status!=='pending'&&g&&isPlayed(g)){const copy={...l};const result=settleBet(copy,g);outcome=result==='won'?'<span class="hit">✓ HIT</span>':result==='void'?'<span class="note">VOID • REFUNDED</span>':'<span class="miss">✗ MISSED</span>';if(copy.actual!==undefined)actual=`<div class="betmeta">Actual: ${copy.actual}</div>`;}return `<div class="slip-leg"><div style="display:flex;justify-content:space-between;gap:10px"><div style="display:flex;align-items:center;gap:8px"><div class="slip-team-stack">${teamLogoForName(betTeamName(l.away,l.awayName),true)}${teamLogoForName(betTeamName(l.home,l.homeName),true)}</div><b>${l.label}</b></div><b>${outcome}</b></div><div class="betmeta">${l.market} • ${l.kind?.startsWith('prop')?'PLAYER PROP':(l.kind==='over'||l.kind==='under'?'GAME TOTAL':l.kind?.startsWith('spr')?'SPREAD':'MONEYLINE')} • ${l.away} @ ${l.home}</div><div style="margin-top:6px;font-weight:800">${l.display}</div>${actual}${g&&isPlayed(g)?`<div class="betmeta">Final: ${g.awayName} ${g.AwayScore} — ${g.HomeScore} ${g.homeName}</div>`:''}</div>`}).join('')}<div class="history-summary"><span>Wager <b>${money(b.wager)}</b></span><span>Odds <b>${b.americanOdds}</b></span><span>${b.status==='pending'?'Potential return':b.status==='won'?'Payout':'P/L'} <b>${b.status==='pending'?money(b.wager*(b.decimalOdds||1)):b.status==='won'?money(b.payout):money(b.profit)}</b></span></div>`;document.getElementById('slipModal').classList.add('show')}

function renderProps(){const c=document.getElementById('propsContent');if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Franchise first.</div>';return}const props=currentData?.playerProps||[];const upcoming=currentGameSet().filter(g=>!isPlayed(g));const propSource=currentData?.summary?.playerPropSource||'historical';const groups=[];for(const g of upcoming){const byPlayer=new Map();for(const p of props){const playerTeamIndex=(p.teamIndex!==null&&p.teamIndex!==undefined)?String(p.teamIndex):null;const awayTeamIndex=(g.awayTeamResolved?.TeamIndex!==null&&g.awayTeamResolved?.TeamIndex!==undefined)?String(g.awayTeamResolved.TeamIndex):null;const homeTeamIndex=(g.homeTeamResolved?.TeamIndex!==null&&g.homeTeamResolved?.TeamIndex!==undefined)?String(g.homeTeamResolved.TeamIndex):null;const side=(playerTeamIndex!==null&&awayTeamIndex!==null&&playerTeamIndex===awayTeamIndex)?'AWAY':(playerTeamIndex!==null&&homeTeamIndex!==null&&playerTeamIndex===homeTeamIndex)?'HOME':(p.teamName&&p.teamName===g.awayName?'AWAY':p.teamName&&p.teamName===g.homeName?'HOME':null);if(!side)continue;const key=String(p.playerId);const entry=byPlayer.get(key)||{playerId:p.playerId,name:p.name,position:p.position,team:p.teamName||side,side,markets:[]};entry.markets.push(p);byPlayer.set(key,entry)}if(byPlayer.size)groups.push({g,players:[...byPlayer.values()]})}if(!groups.length){const d=currentData?.summary?.statMappings?._diagnostic||{};c.innerHTML=`<div class="empty"><b>No player props are available for the selected week.</b><br><br>This franchise did not produce usable player markets for the current matchups.<br><small>Player-stat rows: ${currentData?.summary?.playerGameStatRows??0} • Completed games: ${currentData?.summary?.completedGameCount??0} • Stat links: ${d.ownerLinks??0}</small></div>`;return}const marketOrder={passYds:1,passTD:2,completions:3,rushYds:4,rushAtt:5,recYds:6,receptions:7};groups.sort((a,b)=>gameSort(a.g,b.g));c.innerHTML=`${propSource==='rosterProjection'?'<div class=\"status ok\" style=\"margin-bottom:12px\">Projection mode: this imported franchise has no usable historical player-stat sample yet, so props are calculated from the loaded franchise roster/ratings. No bundled save is used.</div>':''}<div class="prop-games">${groups.map((group,i)=>{const g=group.g;const title=`${g.awayName} @ ${g.homeName}`;const totalMarkets=group.players.reduce((n,p)=>n+p.markets.length,0);return `<details class="prop-game" ${i===0?'open':''}><summary><div style="display:flex;align-items:center;gap:10px"><div class="prop-game-teamlogos">${teamLogoForName(g.awayName,true)}${teamLogoForName(g.homeName,true)}</div><div><div class="prop-game-title">${title}</div><div class="prop-game-meta">${g.phaseLabel||'Regular Season'} • Week ${Number(g.phaseWeek||g.week+1)} • ${String(g.DayOfWeek||'').toUpperCase()} ${formatGameTime(g)} • ${group.players.length} players with ${totalMarkets} markets</div></div></div><span class="prop-game-count">VIEW PROPS ▾</span></summary><div class="prop-players">${group.players.map(p=>{const markets=[...p.markets].sort((a,b)=>(marketOrder[a.stat]||99)-(marketOrder[b.stat]||99));return `<article class="prop-player-card"><div class="prop-player-head"><div style="display:flex;align-items:center;gap:9px;min-width:0">${teamLogoForName(p.team,true)}<div><div class="prop-player-name">${p.name}${p.position&&p.position!=='Invalid_'?' | '+p.position:''}</div><div class="prop-player-info">${p.team} • ${p.markets[0]?.games||0} game sample</div></div></div><span class="tag">${p.side}</span></div><div class="prop-market-grid">${markets.map(m=>{const overOdds=propOdds(m,'over'),underOdds=propOdds(m,'under');return `<div class="prop-market-box"><div class="prop-market-label">${m.label} • Avg ${m.average}</div><div class="prop-market-buttons"><button data-prop='${encodeURIComponent(JSON.stringify({label:`${m.name} O ${m.line} ${m.label}`,market:m.label,display:`O ${m.line} ${fmtOdds(overOdds)}`,odds:overOdds,gameId:gameKey(g),gameIndex:g.index,week:g.week,away:g.awayName,home:g.homeName,kind:'propOver',line:m.line,playerId:m.playerId,propStat:m.stat}))}'><span>OVER</span><b>O ${m.line} <small>${fmtOdds(overOdds)}</small></b></button><button data-prop='${encodeURIComponent(JSON.stringify({label:`${m.name} U ${m.line} ${m.label}`,market:m.label,display:`U ${m.line} ${fmtOdds(underOdds)}`,odds:underOdds,gameId:gameKey(g),gameIndex:g.index,week:g.week,away:g.awayName,home:g.homeName,kind:'propUnder',line:m.line,playerId:m.playerId,propStat:m.stat}))}'><span>UNDER</span><b>U ${m.line} <small>${fmtOdds(underOdds)}</small></b></button></div></div>`}).join('')}</div></article>`}).join('')}</div></details>`}).join('')}</div>`;c.querySelectorAll('[data-prop]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(decodeURIComponent(b.dataset.prop));slip.push({...x,key:crypto.randomUUID()});saveState();renderSlip();setStatus('Player prop added to bet slip.','ok')}))}

