function pickDailyTrivia(){const shuffled=[...triviaBank].sort(()=>Math.random()-.5);const hard=shuffled.filter(q=>q.d===3).slice(0,2);const medium=shuffled.filter(q=>q.d===2).slice(0,2);const easy=shuffled.filter(q=>q.d===1).slice(0,1);return [...hard,...medium,...easy].map(q=>q.id)}
function economyEnsureToday(){const d=todayKey();if(economy.date!==d){economy={date:d,checkIn:false,triviaIds:[],answers:{},perfectPaid:false,filmClicks:0,lastFilmClick:0};}if(economy.triviaVersion!==3){economy.triviaVersion=3;economy.triviaIds=[];economy.answers={};economy.perfectPaid=false;}if(!Array.isArray(economy.triviaIds)||economy.triviaIds.length!==5){economy.triviaIds=pickDailyTrivia();economy.answers={};economy.perfectPaid=false;}return economy}
function economyEarn(amount,reason){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}balance+=Number(amount)||0;saveWallet();setStatus(`${reason} +${money(amount)}.`,'ok');renderEconomy();}
function claimDailyCheckIn(){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();if(economy.checkIn){setStatus('Daily check-in already claimed. Come back tomorrow.','err');return}economy.checkIn=true;economyEarn(25,'Daily check-in');}
function answerTrivia(id,choice){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();if(economy.answers[id]!==undefined)return;const q=triviaBank.find(x=>x.id===id);if(!q)return;const correct=Number(choice)===q.a;economy.answers[id]={choice:Number(choice),correct};if(correct)balance+=20;const allDone=economy.triviaIds.every(x=>economy.answers[x]);if(allDone&&Object.values(economy.answers).filter(x=>x.correct).length===5&&!economy.perfectPaid){economy.perfectPaid=true;balance+=40;}saveWallet();renderEconomy();setStatus(correct?'Correct! +$20.':'Not quite — no reward this time.',correct?'ok':'err');}
function filmRoom(){if(!franchiseLoaded){setStatus('Import a Franchise save before earning bankroll.','err');return}economyEnsureToday();const now=Date.now();const wait=30000-(now-Number(economy.lastFilmClick||0));if(economy.filmClicks>=10){setStatus('Daily Film Room limit reached. Come back tomorrow.','err');return}if(wait>0){setStatus(`Film Room is on cooldown for ${Math.ceil(wait/1000)}s.`,'err');return}economy.filmClicks++;economy.lastFilmClick=now;economyEarn(5,'Film Room');}
function msUntilTomorrow(){const d=new Date();const next=new Date(d);next.setHours(24,0,0,0);return Math.max(0,next-d)}
function formatCountdown(ms){let total=Math.max(0,Math.ceil(ms/1000));const h=Math.floor(total/3600);total%=3600;const m=Math.floor(total/60);const sec=total%60;return h>0?`${h}h ${String(m).padStart(2,'0')}m ${String(sec).padStart(2,'0')}s`:`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function renderEconomy(){const c=document.getElementById('economyContent');if(!c)return;economyEnsureToday();const qs=economy.triviaIds.map(id=>triviaBank.find(q=>q.id===id)).filter(Boolean);const answered=qs.filter(q=>economy.answers[q.id]).length;const correct=qs.filter(q=>economy.answers[q.id]?.correct).length;const filmLeft=Math.max(0,10-Number(economy.filmClicks||0));const wait=Math.max(0,30000-(Date.now()-Number(economy.lastFilmClick||0)));const tomorrow=formatCountdown(msUntilTomorrow());const triviaDone=answered===5;const checkDone=!!economy.checkIn;const filmDone=filmLeft===0;const filmLocked=filmDone||wait>0;const checkStatus=checkDone?`<div class="economy-status"><span>AVAILABLE TOMORROW</span><span class="countdown">${tomorrow}</span></div>`:'';const filmStatus=filmDone?`<div class="economy-status"><span>DAILY LIMIT REACHED</span><span class="countdown">${tomorrow}</span></div>`:wait>0?`<div class="economy-status"><span>NEXT REVIEW IN</span><span class="countdown">${formatCountdown(wait)}</span></div>`:'';const triviaContent=triviaDone?`<div class="trivia-complete"><div class="eyebrow">NFL IQ COMPLETE</div><div class="trivia-countdown">${tomorrow}</div><div class="economy-muted">Trivia available again tomorrow.</div></div>`:`<div class="trivia-list">${qs.map(q=>{const ans=economy.answers[q.id];return `<div class="trivia-card"><div class="trivia-q">${q.q}</div><div class="trivia-options">${q.o.map((opt,i)=>`<button ${ans?'disabled':''} class="${ans?(i===q.a?'correct':i===ans.choice?'wrong':''):''}" data-trivia="${q.id}" data-choice="${i}">${String.fromCharCode(65+i)}. ${opt}</button>`).join('')}</div>${ans?`<div class="trivia-result ${ans.correct?'ok':'err'}">${ans.correct?'Correct — +$20':'Incorrect — the correct answer was '+q.o[q.a]}</div>`:''}</div>`}).join('')}</div>`;c.innerHTML=`<div class="economy-grid"><article class="economy-card"><div class="eyebrow">BANKROLL</div><h3>Economy snapshot</h3><div class="economy-reward">${money(balance)}</div><div class="economy-stat"><span>Trivia correct</span><b>${correct}/${answered||0}</b></div><div class="economy-stat"><span>Film reviews</span><b>${economy.filmClicks}/10</b></div><div class="economy-stat"><span>Daily check-in</span><b>${checkDone?'COMPLETE':'AVAILABLE'}</b></div></article><article class="economy-card"><div class="eyebrow">DAILY CHECK-IN</div><h3>Open the books</h3><div class="economy-reward">+$25</div><div class="economy-muted">One claim per day. Small guaranteed bankroll boost without making betting irrelevant.</div>${checkDone?checkStatus:'<button class="btn primary economy-btn" id="checkInBtn">CLAIM $25</button>'}</article><article class="economy-card"><div class="eyebrow">FILM ROOM</div><h3>Review game film</h3><div class="economy-reward">+$5</div><div class="economy-muted">10 reviews per day, with a 30-second cooldown between reviews. ${filmLeft} reviews remaining.</div><div class="economy-progress"><span style="width:${(Number(economy.filmClicks||0)/10)*100}%"></span></div>${filmLocked?filmStatus:`<button class="btn primary economy-btn" id="filmBtn">REVIEW FILM +$5</button>`}</article></div><article class="economy-card"><div class="eyebrow">NFL IQ</div><h3>Daily Madden / NFL Trivia</h3><div class="economy-muted">5 questions per day with a tougher mix: 2 hard, 2 medium, 1 easy. Correct answer: +$20. Perfect 5/5 bonus: +$40. Wrong answers do not cost anything.</div><div class="economy-progress"><span style="width:${(answered/5)*100}%"></span></div>${triviaContent}</article>`;c.querySelector('#checkInBtn')?.addEventListener('click',claimDailyCheckIn);c.querySelector('#filmBtn')?.addEventListener('click',filmRoom);c.querySelectorAll('[data-trivia]').forEach(b=>b.addEventListener('click',()=>answerTrivia(b.dataset.trivia,Number(b.dataset.choice))));}

function setStatus(t,c=''){const e=document.getElementById('status');e.textContent=t;e.className='status '+c}
function showPage(p){activePage=p;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p+'Page').classList.add('active');if(p==='games')renderGames();if(p==='standings')renderStandings();if(p==='active')renderActiveBets();if(p==='history')renderHistory();if(p==='stats')renderStats();if(p==='props')renderProps();if(p==='economy')renderEconomy()}
function phaseLabel(phase){return phase==='preseason'?'Preseason':phase==='playoffs'?'Playoffs':phase==='superbowl'?'Super Bowl':'Regular Season'}
function setPhaseOptions(phaseWeeks){document.querySelectorAll('#phasebar [data-phase]').forEach(b=>{const phase=b.dataset.phase;const count=(phaseWeeks[phase]||[]).length;b.style.display=count?'inline-block':'none';b.title=count?`${count} week${count===1?'':'s'} available`:'No games loaded for this phase';});}
function populatePhaseWeeks(phase,preferred){const weeks=(currentData?.summary?.phaseWeeks?.[phase]||[]).map(Number).filter(Number.isFinite);const sel=document.getElementById('week');sel.innerHTML=weeks.map(w=>`<option value="${w}">${w}</option>`).join('');let pick=Number(preferred);if(!weeks.includes(pick))pick=weeks[0]??1;sel.value=String(pick);document.getElementById('weekLabel').textContent=phaseLabel(phase)+' Week';document.getElementById('title').textContent=`${phaseLabel(phase)} • Week ${pick}`;document.querySelectorAll('#phasebar [data-phase]').forEach(x=>x.classList.toggle('active',x.dataset.phase===phase));}
async function loadResult(result){document.getElementById('modalText').textContent=JSON.stringify(result,null,2);if(!result.ok){document.getElementById('startupStatus').textContent='Import failed. Choose another Franchise save.';document.getElementById('startupStatus').className='startup-status err';setStatus('Parser error. See Import / Refresh Result.','err');document.getElementById('modal').classList.add('show');return}franchiseLoaded=true;currentData=result;activateWallet(currentFranchiseKey());games=(result.games||[]).map(g=>{const at=g.awayTeamResolved||{},ht=g.homeTeamResolved||{};return{...g,week:Number(g.SeasonWeek),awayName:teamName(at),homeName:teamName(ht),awayAb:teamAb(at),homeAb:teamAb(ht)}});teams=result.teams||[];document.getElementById('dataTag').textContent='LIVE SAVE';document.getElementById('franchiseName').textContent=result.fileName+' • Madden '+result.gameYear+' • '+result.summary.playableGames+' games imported';setPhaseOptions(result.summary.phaseWeeks||{});const current=Number.isFinite(Number(result.summary.activeSeasonWeek))?Number(result.summary.activeSeasonWeek)+1:1;window.selectedPhase=(result.summary.phaseWeeks?.regular||[]).includes(current)?'regular':(Object.keys(result.summary.phaseWeeks||{}).find(k=>(result.summary.phaseWeeks[k]||[]).length)||'regular');populatePhaseWeeks(window.selectedPhase,current);document.getElementById('title').textContent=`${phaseLabel(window.selectedPhase)} • Week ${Number(document.getElementById('week').value)||1}`;settlePending();renderGames();renderStandings();renderActiveBets();renderHistory();renderStats();renderProps();renderBalance();document.body.classList.remove('startup-locked');document.getElementById('startupGate').classList.add('hidden');setStatus(`Franchise loaded. Active Madden Week ${current+1}. Lines are generated from Franchise data.`,'ok')}
async function importFranchiseFromPicker(){try{document.getElementById('startupStatus').textContent='Parsing Franchise save…';document.getElementById('startupStatus').className='startup-status';setStatus('Parsing Franchise…');const p=await window.maddenAPI.pickFranchise();if(!p||p.canceled){document.getElementById('startupStatus').textContent='Waiting for a Franchise save…';return}const r=await window.maddenAPI.parseFranchise(p.path);await loadResult(r)}catch(e){document.getElementById('startupStatus').textContent='Import error: '+e.message;document.getElementById('startupStatus').className='startup-status err';setStatus('Import error: '+e.message,'err')}}
document.getElementById('importBtn').addEventListener('click',importFranchiseFromPicker);document.getElementById('startupImportBtn').addEventListener('click',importFranchiseFromPicker);document.getElementById('startupImportBtn').onclick=importFranchiseFromPicker;
document.getElementById('refreshBtn').addEventListener('click',async()=>{try{if(!franchiseLoaded){setStatus('Import a Franchise first.','err');return}setStatus('Refreshing saved Franchise…');const r=await window.maddenAPI.reparseFranchise();await loadResult(r);setStatus('Save refreshed. Any completed pending bets were settled.','ok')}catch(e){setStatus('Refresh error: '+e.message,'err')}});
async function autoRefreshFromSaveChange(){if(!autoRefresh||!franchiseLoaded||autoRefreshBusy)return;autoRefreshBusy=true;try{setStatus('Madden AUTOSAVE changed — refreshing sportsbook…','ok');let r=null;let lastErr=null;for(let i=0;i<4;i++){try{r=await window.maddenAPI.reparseFranchise();if(r?.ok)break;lastErr=new Error(r?.error||'Save is still being written.');}catch(e){lastErr=e}await new Promise(x=>setTimeout(x,900));}if(r?.ok){await loadResult(r);setStatus('Autosave detected — sportsbook updated automatically.','ok')}else{throw lastErr||new Error('Unable to refresh the save.')}}catch(e){setStatus('Auto-refresh failed. The Madden save may still be writing; use Refresh Save when ready.','err')}finally{autoRefreshBusy=false}}
window.maddenAPI.onFranchiseSaveChanged(()=>autoRefreshFromSaveChange());
document.getElementById('week').addEventListener('change',()=>{const w=Number(document.getElementById('week').value);document.getElementById('title').textContent=`${phaseLabel(window.selectedPhase||'regular')} • Week ${w}`;renderGames();renderProps()});document.querySelectorAll('#phasebar [data-phase]').forEach(b=>b.addEventListener('click',()=>{window.selectedPhase=b.dataset.phase;populatePhaseWeeks(window.selectedPhase);document.querySelectorAll('#phasebar [data-phase]').forEach(x=>x.classList.toggle('active',x===b));renderGames();renderProps();}));document.getElementById('wager').addEventListener('input',renderSlip);document.getElementById('placeBtn').addEventListener('click',placeBet);document.getElementById('clearSlip').addEventListener('click',()=>{slip=[];saveState();renderSlip()});document.getElementById('copyLog').addEventListener('click',async()=>{const text=document.getElementById('modalText').textContent||'';try{await navigator.clipboard.writeText(text);setStatus('Import log copied to clipboard.','ok')}catch{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();setStatus('Import log copied to clipboard.','ok')}});document.getElementById('closeModal').addEventListener('click',()=>document.getElementById('modal').classList.remove('show'));document.getElementById('closeSlipModal').addEventListener('click',()=>document.getElementById('slipModal').classList.remove('show'));document.getElementById('earnBtn').addEventListener('click',()=>showPage('economy'));document.getElementById('closeBalanceModal').addEventListener('click',()=>document.getElementById('balanceModal').classList.remove('show'));document.getElementById('confirmBalanceBtn').addEventListener('click',()=>{const amount=Math.max(0,Number(document.getElementById('balanceAmount').value)||0);if(!amount){setStatus('Enter an amount to add.','err');return}if(!franchiseLoaded){setStatus('Import a Franchise before adding test funds.','err');return}balance+=amount;saveWallet();document.getElementById('balanceModal').classList.remove('show');setStatus(`Added ${money(amount)} to bankroll.`,'ok');renderEconomy()});window.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='0'){e.preventDefault();if(!franchiseLoaded){setStatus('Import a Franchise before using test balance.','err');return}document.getElementById('balanceModalSave').textContent=`Current save: ${currentFranchiseLabel()}`;document.getElementById('balanceModal').classList.add('show');document.getElementById('balanceAmount').focus();document.getElementById('balanceAmount').select()}});document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));loadTheme();initThemeControls();document.body.classList.add('startup-locked');(async()=>{await loadState();renderBalance();renderSlip();renderActiveBets();renderHistory();renderProps();showPage('economy');document.body.classList.remove('startup-locked');})();setInterval(()=>{if(activePage==='economy'&&franchiseLoaded)renderEconomy()},1000);
